entries[16040] = { ["name"] = "Arkane Bombe", ["text"] = "Benötigt Ingenieurskunst (300)\nBenutzen: Zieht 675 bis 1125 Punkt(e) Mana von allen ab, die sich im Umkreis des Schlages befinden und fügt dem Ziel einen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Schlagbereich außerdem 5 Sek. lang zum Schweigen. (1 Min Abklingzeit)" }
entries[16041] = { ["name"] = "Bauplan: Thoriumgranate", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung einer Thoriumgranate.\nThoriumgranate\nBenötigt Ingenieurskunst (260)\nBenutzen: Fügt 300 bis 500 Feuerschaden zu und betäubt Ziele 3 Sek. lang in einem Umkreis von 3 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\nBenötigt Thoriumapparat , Thoriumbarren (3), Dichtes Sprengpulver (3), Runenstoff (3)" }
entries[16042] = { ["name"] = "Bauplan: Thoriumapparat", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung eines Thoriumapparates.\nThoriumapparat\nBenötigt Thoriumbarren (3), Runenstoff" }
entries[16043] = { ["name"] = "Bauplan: Thoriumgewehr", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung eines Thoriumgewehrs.\nThoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n42 - 79 Schaden Tempo 2.50\n(24.20 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 47\nAnlegen: +17 Distanzangriffskraft.\nBenötigt Mithrilrohr (2), Mithrilgehäuse (2), Thoriumapparat (2), Thoriumbarren (4), Tödliches Zielfernrohr" }
entries[16044] = { ["name"] = "Bauplan: Lebensechte mechanische Kröte", ["text"] = "Benötigt Ingenieurskunst (265)\nBenutzen: Lehrt Euch die Herstellung einer lebensechten mechanischen Kröte.\nLebensechte mechanische Kröte\nWird bei Benutzung gebunden\nBenutzen: Mit Rechtsklick Eure lebensechte mechanische Kröte beschwören und freigeben.\nBenötigt Essenz des Lebens , Thoriumapparat (4), Goldkraftkern , Unverwüstliches Leder" }
entries[16045] = { ["name"] = "Bauplan: Zaubermachtschutzbrille Xtrem Plus", ["text"] = "Benötigt Ingenieurskunst (270)\nBenutzen: Lehrt Euch die Herstellung einer Zaubermachtschutzbrille Xtrem Plus.\nZaubermachtschutzbrille Xtrem Plus\nWird beim Anlegen gebunden\nKopf Stoff\n57 Rüstung\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (270)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 27.\nBenötigt Zaubermachtschutzbrille Xtrem , Sternrubin (4), Verzaubertes Leder (2), Runenstoff (8)" }
entries[16046] = { ["name"] = "Bauplan: Meisterliche Zielattrappe", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung einer meisterlichen Zielattrappe.\nMeisterliche Zielattrappe\nBenötigt Ingenieurskunst (275)\nBenutzen: Lässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden. (2 Min Abklingzeit)\nBenötigt Mithrilgehäuse , Thoriumröhre , Thoriumapparat (2), Echtsilberbarren , Unverwüstliches Leder (2), Runenstoff (4)" }
entries[16047] = { ["name"] = "Bauplan: Thoriumröhre", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung einer Thoriumröhre.\nThoriumröhre\nBenötigt Thoriumbarren (6)" }
entries[16048] = { ["name"] = "Bauplan: Dunkeleisengewehr", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung eines Dunkeleisengewehrs.\nDunkeleisengewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n53 - 100 Schaden Tempo 2.70\n(28.33 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 50\nAnlegen: Gewährt eine Chance, Euer Distanzziel mit einem Schattenschuss zu treffen und 18 bis 26 Schattenschaden zu verursachen.\nBenötigt Thoriumröhre (2), Dunkeleisenbarren (6), Tödliches Zielfernrohr (2), Blauer Saphir (2), Großer Opal (2), Unverwüstliches Leder (4)" }
entries[16049] = { ["name"] = "Bauplan: Dunkeleisenbombe", ["text"] = "Benötigt Ingenieurskunst (285)\nBenutzen: Lehrt Euch die Herstellung einer Dunkeleisenbombe.\nDunkeleisenbombe\nBenötigt Ingenieurskunst (285)\nBenutzen: Fügt 225 bis 675 Feuerschaden zu und betäubt Ziele 4 Sek. lang in einem Umkreis von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)\nBenötigt Thoriumapparat (2), Dunkeleisenbarren , Dichtes Sprengpulver (3), Runenstoff (3)" }
entries[16050] = { ["name"] = "Bauplan: Empfindlicher Arkanitwandler", ["text"] = "Benötigt Ingenieurskunst (285)\nBenutzen: Lehrt Euch die Herstellung eines empfindlichen Arkanitwandlers.\nEmpfindlicher Arkanitwandler\nBenötigt Arkanitbarren , Eisenweberseide" }
entries[16051] = { ["name"] = "Bauplan: Thoriumpatronen", ["text"] = "Benötigt Ingenieurskunst (285)\nBenutzen: Lehrt Euch die Herstellung von Thoriumpatronen.\nThoriumpatronen\nMunition Kugel\nVerursacht 17.5 zusätzlichen Schaden pro Sekunde.\nBenötigt Stufe 52\nBenötigt Thoriumbarren (2), Dichtes Sprengpulver" }
entries[16052] = { ["name"] = "Bauplan: Modularer Stimmenverstärker", ["text"] = "Benötigt Ingenieurskunst (290)\nBenutzen: Lehrt Euch die Herstellung eines Modularen Stimmenverstärkers.\nModularer Stimmenverstärker\nWird beim Anlegen gebunden\nHals\nAnlegen: Erhöht Euren Widerstand gegen Stilleeffekte um 7%.\nBenötigt Empfindlicher Arkanitwandler (2), Goldkraftkern , Thoriumapparat , Großer Opal" }
entries[16053] = { ["name"] = "Bauplan: Schutzbrille des Meisteringenieurs", ["text"] = "Benötigt Ingenieurskunst (290)\nBenutzen: Lehrt Euch die Herstellung einer Schutzbrille des Meisteringenieurs.\nSchutzbrille des Meisteringenieurs\nWird beim Anlegen gebunden\nKopf Stoff\n61 Rüstung\n+16 Ausdauer\n+17 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (280)\nBenötigt Feuerschutzbrille , Gewaltiger Smaragd (2), Verzaubertes Leder (4)" }
entries[16054] = { ["name"] = "Bauplan: Arkanitdrachling", ["text"] = "Benötigt Ingenieurskunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Arkanitdrachlings.\nArkanitdrachling\nWird beim Anlegen gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (300)\nBenutzen: Aktiviert Euren Arkanitdrachling, damit er 1 Min. lang für Euch kämpft. Benötigt eine Stunde Abklingzeit, bevor ein erneuter Einsatz möglich wird. (1 Stunde Abklingzeit)\nBenötigt Mechanischer Mithrildrachling , Empfindlicher Arkanitwandler (8), Verzauberter Thoriumbarren (10), Thoriumapparat (6), Goldkraftkern (4), Verzaubertes Leder (6)" }
entries[16055] = { ["name"] = "Bauplan: Arkane Bombe", ["text"] = "Benötigt Ingenieurskunst (300)\nBenutzen: Lehrt Euch die Herstellung einer arkanen Bombe.\nArkane Bombe\nBenötigt Ingenieurskunst (300)\nBenutzen: Zieht 675 bis 1125 Punkt(e) Mana von allen ab, die sich im Umkreis des Schlages befinden und fügt dem Ziel einen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Schlagbereich außerdem 5 Sek. lang zum Schweigen. (1 Min Abklingzeit)\nBenötigt Empfindlicher Arkanitwandler , Thoriumbarren (3), Runenstoff" }
entries[16056] = { ["name"] = "Bauplan: Fehlerloses Arkanitgewehr", ["text"] = "Benötigt Ingenieurskunst (300)\nBenutzen: Lehrt Euch die Herstellung eines fehlerlosen Arkanitgewehrs.\nFehlerloses Arkanitgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n65 - 122 Schaden Tempo 3.00\n(31.17 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 56\nAnlegen: Schusswaffen +4.\nAnlegen: +10 Distanzangriffskraft.\nBenötigt Arkanitbarren (10), Thoriumröhre (2), Essenz des Feuers (2), Essenz der Erde (2), Azerothianischer Diamant (2), Verzaubertes Leder (2)" }
