entries[17200] = { ["name"] = "Rezept: Lebkuchen", ["text"] = "Benötigt Kochkunst (1)\nBenutzen: Lehrt Euch, wie man Lebkuchen backt.\nLebkuchen\nBenutzen: Stellt im Verlauf von 18 Sek. 61.2 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Punkt(e) Ausdauer und Willenskraft.\nBenötigt Kleines Ei , Festtagsgewürze" }
entries[17201] = { ["name"] = "Rezept: Eierflip", ["text"] = "Benötigt Kochkunst (35)\nBenutzen: Lehrt Euch die Herstellung von Eierflip.\nEierflip\nBenutzen: Stellt im Verlauf von 18 Sek. 61.2 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Punkt(e) Ausdauer und Willenskraft. Hat es außerdem ganz schön in sich...\nBenötigt Kleines Ei , Eiskalte Milch , Festtagsgeister , Festtagsgewürze" }
